parts.headerCss:
.tpl-header .header{
  display:flex;
  justify-content:space-between;
  align-items:flex-start;
  gap:16px;
}
.tpl-header .brand{
  font-size:28px;
  font-weight:800;
  letter-spacing:-0.02em;
}
.tpl-header .meta{
  text-align:right;
  font-size:13px;
  color:#6b7280;
}
.tpl-header .invoice-number{
  font-weight:700;
  color:#111827;
}

parts.bodyCss:
.tpl-body{
  padding-top:16px;
}
.tpl-body .bill-to .label{
  font-size:11px;
  letter-spacing:0.08em;
  text-transform:uppercase;
  color:#9ca3af;
}
.tpl-body .bill-to .name{
  font-weight:700;
}
.tpl-body .bill-to .company{
  color:#6b7280;
}
.tpl-body hr{
  border:none;
  border-top:1px solid #e5e7eb;
  margin:16px 0;
}
.tpl-body .total{
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-top:18px;
  padding:10px 12px;
  border:1px solid #e5e7eb;
  border-radius:10px;
  background:#fafafa;
}

parts.footerCss:
.tpl-footer{
  margin-top:18px;
  padding-top:12px;
  border-top:1px solid #e5e7eb;
  font-size:12px;
  color:#9ca3af;
  text-align:center;
}
